app.post('/verify-code', async (req, res) => { try { const { token, email, code } = req.body; if(!token||!email||!code) return res.send(`<script>alert('All fields required!');window.location.href='/forgot-password'</script>`); if(dbConnected){const [users]=await db.query(`SELECT * FROM users WHERE email=$1 AND reset_token=$2 AND verification_code=$3 AND reset_token_expires > NOW()`,{bind:[email,token,code]}); if(users.length===0) return res.send(`<!DOCTYPE html><html><head><title>Invalid</title><style>*{margin:0}body{font-family:Arial,sans-serif;background:#f5f5f5;display:flex;justify-content:center;align-items:center;min-height:100vh}.box{background:white;padding:35px;border-radius:15px;text-align:center}h2{color:#dc3545}.btn{display:inline-block;padding:12px 25px;background:#1a237e;color:white;text-decoration:none;border-radius:8px;font-weight:bold;margin:10px}</style></head><body><div class="box"><h2>❌ Invalid Code!</h2><p>Code incorrect or expired.</p><a href="/forgot-password" class="btn">🔄 Try Again</a></div></body></html>`);} res.redirect(`/reset-password?token=${token}&verified=true`); } catch(e) { res.send(`<script>alert('Error');window.location.href='/forgot-password'</script>`); } });
app.get('/reset-password', async (req, res) => { const { token, verified } = req.query; if(!token||!verified) return res.redirect('/forgot-password'); if(dbConnected){const [users]=await db.query(`SELECT * FROM users WHERE reset_token=$1 AND reset_token_expires > NOW()`,{bind:[token]}); if(users.length===0) return res.send(`<script>alert('Expired!');window.location.href='/forgot-password'</script>`);} res.send(`<!DOCTYPE html><html><head><title>Reset</title><meta charset="UTF-8">${BSI}<style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Arial,sans-serif;background:linear-gradient(135deg,#28a745,#218838);display:flex;justify-content:center;align-items:center;min-height:100vh}.box{background:white;padding:35px;border-radius:15px;box-shadow:0 10px 30px rgba(0,0,0,0.2);width:100%;max-width:420px}h2{color:#28a745;text-align:center}.verified{background:#d4edda;color:#155724;padding:10px;border-radius:8px;text-align:center;margin-bottom:20px;font-weight:bold}.input-group{position:relative;margin:10px 0}.input-group input{width:100%;padding:14px;border:2px solid #e0e0e0;border-radius:8px;font-size:16px}.input-group input[type="password"]{padding-right:45px}${CSS}button{width:100%;padding:14px;background:#1a237e;color:white;border:none;border-radius:8px;font-size:16px;font-weight:bold;cursor:pointer;margin-top:10px}.link{text-align:center;margin-top:15px}.link a{color:#1a237e;text-decoration:none}</style></head><body><div class="box"><h2>🔑 Reset Password</h2><div class="verified">✅ Enter New Password</div><form action="/reset-password" method="POST"><input type="hidden" name="token" value="${token}"><div class="input-group"><input type="password" name="password" id="np1" placeholder="New Password (min 6)" minlength="6" required><span class="toggle-password" onclick="togglePass('np1',this)"><i class="bi bi-eye"></i></span></div><div class="input-group"><input type="password" name="confirmPassword" id="np2" placeholder="Confirm Password" minlength="6" required><span class="toggle-password" onclick="togglePass('np2',this)"><i class="bi bi-eye"></i></span></div><button type="submit">🔐 Update</button></form><div class="link"><a href="/login">← Login</a></div></div><script>${JS}</script></body></html>`); });
app.post('/reset-password', async (req, res) => { try { const { token, password, confirmPassword } = req.body; if(!token||!password||!confirmPassword) return res.send(`<script>alert('All fields required!');</script>`); if(password!==confirmPassword) return res.send(`<script>alert('Passwords do not match!');</script>`); if(password.length<6) return res.send(`<script>alert('Min 6 characters!');</script>`); if(dbConnected){const [users]=await db.query(`SELECT * FROM users WHERE reset_token=$1 AND reset_token_expires > NOW()`,{bind:[token]}); if(users.length===0) return res.send(`<script>alert('Expired!');window.location.href='/forgot-password'</script>`); const hash=await bcrypt.hash(password,12); await db.query(`UPDATE users SET password=$1,reset_token=NULL,reset_token_expires=NULL,verification_code=NULL WHERE reset_token=$2`,{bind:[hash,token]});} res.send(`<!DOCTYPE html><html><head><title>Updated</title><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:linear-gradient(135deg,#28a745,#218838);display:flex;justify-content:center;align-items:center;min-height:100vh}.box{background:white;padding:35px;border-radius:15px;text-align:center}h2{color:#28a745}.btn{display:inline-block;padding:12px 25px;background:#1a237e;color:white;text-decoration:none;border-radius:8px;font-weight:bold}</style></head><body><div class="box"><h2>✅ Password Updated!</h2><a href="/login" class="btn">🔐 Login</a></div></body></html>`); } catch(e) { res.send(`<script>alert('Error');window.location.href='/login'</script>`); } });

