app.get('/student/courses/:courseId/lessons', auth, async (req, res) => { const courseId=req.params.courseId; let course={title:'Course'},lessons=[],hasAccess=false; if(dbConnected){try{const [c]=await db.query(`SELECT * FROM courses WHERE id=$1`,{bind:[courseId]});if(c.length>0)course=c[0];const [e]=await db.query(`SELECT * FROM enrollments WHERE user_id=$1 AND course_id=$2 AND status='active' AND payment_status='verified'`,{bind:[req.session.userId,courseId]});hasAccess=e.length>0;if(hasAccess){const [l]=await db.query(`SELECT * FROM lessons WHERE course_id=$1 ORDER BY order_number`,{bind:[courseId]});lessons=l;}}catch(e){}} if(!hasAccess) return res.send(`<!DOCTYPE html><html><head><title>Access Denied</title><meta charset="UTF-8"><style>*{margin:0}body{font-family:Arial,sans-serif;background:linear-gradient(135deg,#dc3545,#c82333);display:flex;justify-content:center;align-items:center;min-height:100vh}.card{background:white;padding:40px;border-radius:20px;text-align:center}.icon{font-size:70px}h2{color:#dc3545}.btn{display:inline-block;padding:12px 25px;background:#1a237e;color:white;text-decoration:none;border-radius:8px;font-weight:bold;margin:10px}.btn-wa{background:#25D366}</style></head><body><div class="card"><div class="icon">🔒</div><h2>Payment Required!</h2><p>Pay to access lessons.</p><a href="/student/payment" class="btn btn-wa">💰 Pay Now</a><a href="/student/courses" class="btn">← Back</a></div></body></html>`); let ll=''; if(lessons.length>0){lessons.forEach(l=>{ll+=`<div class="lesson-card"><h3>📖 ${l.title}</h3><p>📚 ${l.topic_name||'Chemistry'}</p><div class="actions">${l.zoom_link?`<a href="${l.zoom_link}" target="_blank" class="ab live"><span>📡</span>Live</a>`:`<div class="ab inactive"><span>📡</span>N/A</div>`}${l.video_url?`<a href="${l.video_url}" target="_blank" class="ab recording"><span>🎬</span>Recording</a>`:`<div class="ab inactive"><span>🎬</span>N/A</div>`}</div></div>`;});}else{ll='<p style="text-align:center;padding:30px;">No lessons.</p>';} res.send(`<!DOCTYPE html><html><head><title>${course.title}</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#28a745,#218838);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.badge{background:rgba(255,255,255,0.2);padding:5px 15px;border-radius:20px}.back{color:white;text-decoration:none}.container{max-width:800px;margin:25px auto;padding:0 20px}.lesson-card{background:white;padding:25px;border-radius:15px;box-shadow:0 5px 15px rgba(0,0,0,0.08);margin-bottom:20px}.lesson-card h3{color:#1a237e}.actions{display:flex;gap:20px;flex-wrap:wrap}.ab{flex:1;min-width:200px;padding:25px 20px;border-radius:12px;text-align:center;text-decoration:none;color:white;display:flex;flex-direction:column;align-items:center;gap:8px}.live{background:linear-gradient(135deg,#dc3545,#c82333)}.recording{background:linear-gradient(135deg,#1a237e,#283593)}.inactive{opacity:0.5;pointer-events:none}</style></head><body><div class="header"><h1>📚 ${course.title}</h1><div><span class="badge">✅ Paid</span><a href="/student/courses" class="back">← Courses</a></div></div><div class="container"><h2>Lessons</h2><p style="color:#666;">👨‍🏫 ${T.name}</p>${ll}</div></body></html>`); });

