app.get('/admin/profile', adminAuth, async (req, res) => { let admin = { full_name: T.name, profile_image: '' }; if (dbConnected) { try { const [rows] = await db.query(`SELECT * FROM users WHERE username='Buddika' AND role='admin'`); if (rows.length > 0) admin = rows[0]; } catch(e) {} } const imgD = admin.profile_image ? `<img src="/uploads/${admin.profile_image}" style="width:120px;height:120px;border-radius:50%;object-fit:cover;border:4px solid #1a237e;margin-bottom:15px;">` : '<div style="width:120px;height:120px;border-radius:50%;background:#1a237e;display:flex;align-items:center;justify-content:center;font-size:50px;color:white;margin:0 auto 15px;">👨‍🏫</div>'; res.send(`<!DOCTYPE html><html><head><title>Profile</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.logout{background:#dc3545;color:white;padding:8px 18px;border-radius:5px;text-decoration:none}.container{max-width:600px;margin:30px auto;padding:0 20px}.card{background:white;padding:30px;border-radius:15px;box-shadow:0 5px 15px rgba(0,0,0,0.08);text-align:center}h2{color:#1a237e}.upload-area{background:#f9f9f9;border:3px dashed #ccc;border-radius:15px;padding:30px;margin:20px 0;cursor:pointer}.upload-area:hover{border-color:#1a237e}input[type="file"]{display:none}button{width:100%;padding:14px;background:#28a745;color:white;border:none;border-radius:8px;font-size:16px;font-weight:bold;cursor:pointer;margin-top:10px}.back-link{display:inline-block;margin-top:15px;color:#1a237e;text-decoration:none}.success{background:#d4edda;color:#155724;padding:12px;border-radius:8px;margin-bottom:20px;font-weight:bold}</style></head><body><div class="header"><h1>👨‍🏫 Profile</h1><a href="/logout" class="logout">🚪 Logout</a></div><div class="container">${req.query.uploaded ? '<div class="success">✅ Photo Updated!</div>' : ''}<div class="card"><h2>${T.name}</h2>${imgD}<form action="/admin/profile/upload" method="POST" enctype="multipart/form-data"><div class="upload-area" onclick="document.getElementById('photoFile').click()"><p style="font-size:40px;">📷</p><p>Click to Select</p></div><input type="file" id="photoFile" name="photo" accept="image/*" onchange="previewImage(this)" required><img id="preview" style="width:120px;height:120px;border-radius:50%;object-fit:cover;border:4px solid #1a237e;margin:15px auto;display:none;"><br><button type="submit">💾 Upload</button></form><a href="/admin/dashboard" class="back-link">← Dashboard</a></div></div><script>function previewImage(input){var p=document.getElementById('preview');if(input.files&&input.files[0]){var r=new FileReader();r.onload=function(e){p.src=e.target.result;p.style.display='block';document.querySelector('.upload-area').style.display='none'};r.readAsDataURL(input.files[0])}}</script></body></html>`); });
app.post('/admin/profile/upload', adminAuth, upload.single('photo'), async (req, res) => { try { if (!req.file) return res.send(`<script>alert('Select photo!');window.location.href='/admin/profile'</script>`); if (dbConnected) { await db.query(`UPDATE users SET profile_image=$1 WHERE username='Buddika' AND role='admin'`, { bind: [req.file.filename] }); } res.redirect('/admin/profile?uploaded=1'); } catch(e) { res.send(`<script>alert('Error');window.location.href='/admin/profile'</script>`); } });

