app.get('/admin/password-requests', adminAuth, async (req, res) => {
    if (req.session.userRole === 'sub_admin') { const p = await getPerms(req.session.userId); if (!p.can_send_reset_codes) return res.send(`<h2>⛔ Access Denied</h2><a href="/admin/dashboard">← Back</a>`); }
    let requests=[]; if(dbConnected){try{const [rows]=await db.query(`SELECT student_id,full_name,email,mobile_number,verification_code,reset_token_expires FROM users WHERE role='student' AND verification_code IS NOT NULL AND reset_token_expires > NOW() ORDER BY reset_token_expires DESC`);requests=rows;}catch(e){}} let tr=''; if(requests.length>0){requests.forEach(r=>{tr+=`<tr><td><strong>${r.student_id}</strong></td><td>${r.full_name}</td><td>${r.email}</td><td>${r.mobile_number}</td><td><span style="background:#1a237e;color:white;padding:5px 15px;border-radius:5px;font-size:18px;font-weight:bold;letter-spacing:3px">${r.verification_code}</span></td><td>${new Date(r.reset_token_expires).toLocaleString()}</td><td><a href="/admin/send-code-email?email=${encodeURIComponent(r.email)}&name=${encodeURIComponent(r.full_name)}&code=${r.verification_code}" class="btn-mini" style="background:#2563eb;">📧 Email Code</a></td></tr>`;});}else{tr='<tr><td colspan="7" style="text-align:center;padding:30px;color:#28a745;">✅ No pending requests!</td></tr>';} res.send(`<!DOCTYPE html><html><head><title>Password Requests</title><meta charset="UTF-8"><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:1100px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08)}h2{color:#1a237e}table{width:100%;border-collapse:collapse}th{background:#1a237e;color:white;padding:12px;text-align:left;font-size:13px}td{padding:12px;border-bottom:1px solid #eee;font-size:14px}.btn-mini{padding:8px 16px;border-radius:5px;text-decoration:none;font-size:12px;font-weight:bold;display:inline-block;color:white}.count{background:#fff3cd;color:#856404;padding:10px 20px;border-radius:8px;display:inline-block;margin-bottom:15px;font-weight:bold}</style></head><body><div class="header"><h1>🔑 Reset Requests</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="card"><h2>Pending</h2><div class="count">📋 ${requests.length}</div><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Mobile</th><th>Code</th><th>Expires</th><th>Action</th></tr></thead><tbody>${tr}</tbody></table></div></div></body></html>`); });
app.get('/admin/send-code-email', adminAuth, async (req, res) => { const { email, name, code } = req.query; if(!email || !code) return res.send(`<script>alert('Missing data!');window.location.href='/admin/password-requests'</script>`); let emailSent = false; try { const nodemailer = require('nodemailer'); const transporter = nodemailer.createTransport({ host: process.env.EMAIL_HOST || 'smtp.gmail.com', port: parseInt(process.env.EMAIL_PORT || '465'), secure: true, auth: { user: process.env.EMAIL_USER || '', pass: process.env.EMAIL_PASS || '' }, connectionTimeout: 5000 }); await transporter.sendMail({ from: `"${T.name} LMS" <${process.env.EMAIL_USER || 'noreply@chemistry.lk'}>`, to: email, subject: 'Password Reset Code - ' + T.name, html: `<div style="max-width:500px;margin:0 auto;padding:30px;font-family:Arial,sans-serif;background:#f5f5f5;border-radius:10px"><div style="text-align:center;font-size:50px">⚗️</div><h2 style="color:#1a237e;text-align:center">Password Reset Code</h2><p style="color:#666;text-align:center">Hello, ${name||'Student'}!</p><p style="color:#666;text-align:center">Your code is:</p><div style="background:#1a237e;color:white;padding:20px;border-radius:10px;text-align:center;font-size:36px;font-weight:bold;letter-spacing:10px;margin:20px 0">${code}</div><p style="color:#666;text-align:center">⚠️ Expires in 1 hour.</p></div>` }); emailSent = true; } catch(e) { console.error(e.message); } res.send(`<!DOCTYPE html><html><head><title>Email</title><meta charset="UTF-8"><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5;display:flex;justify-content:center;align-items:center;min-height:100vh}.box{background:white;padding:35px;border-radius:15px;box-shadow:0 10px 30px rgba(0,0,0,0.1);width:100%;max-width:450px;text-align:center}h2{color:${emailSent?'#28a745':'#dc3545'}}p{color:#666}.btn{display:inline-block;padding:12px 25px;background:#1a237e;color:white;text-decoration:none;border-radius:8px;font-weight:bold;margin:10px}.info{background:#e3f2fd;color:#1565c0;padding:15px;border-radius:8px;margin:15px 0}</style></head><body><div class="box"><h2>${emailSent ? '✅ Email Sent!' : '❌ Failed!'}</h2><p>${emailSent ? 'Code sent to:' : 'Unable to send to:'}<br><strong>${email}</strong></p>${emailSent ? '<div class="info">📧 Code: <strong>'+code+'</strong><br>Student: <strong>'+name+'</strong></div>' : '<p style="color:#dc3545;">Check email settings.</p>'}<a href="/admin/password-requests" class="btn">← Back</a></div></body></html>`); });

