app.get('/admin/delete-requests', adminAuth, async (req, res) => { if (req.session.userRole !== 'admin') return res.send(`<h2>⛔ Only Main Admin</h2><a href="/admin/dashboard">← Back</a>`); let requests = []; if (dbConnected) { try { const [rows] = await db.query(`SELECT u.*, r.full_name as requester_name FROM users u LEFT JOIN users r ON u.delete_requested_by = r.id WHERE u.delete_requested = true AND u.role='student'`); requests = rows; } catch(e) {} } let tr = ''; requests.forEach(s => { tr += `<tr><td><strong>${s.student_id}</strong></td><td>${s.full_name}</td><td>${s.email}</td><td>${s.last_login_at ? new Date(s.last_login_at).toLocaleDateString() : 'Never'}</td><td>${s.requester_name || 'Auto'}</td><td><a href="/admin/delete-requests/approve/${s.id}" class="btn-mini btn-danger" onclick="return confirm('Delete?')">✅ Delete</a><a href="/admin/delete-requests/reject/${s.id}" class="btn-mini">❌ Reject</a></td></tr>`; }); res.send(`<!DOCTYPE html><html><head><title>Delete Requests</title><meta charset="UTF-8"><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#dc3545,#c82333);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:1100px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08)}h2{color:#dc3545}table{width:100%;border-collapse:collapse}th{background:#dc3545;color:white;padding:12px;text-align:left;font-size:13px}td{padding:12px;border-bottom:1px solid #eee;font-size:13px}.btn-mini{padding:5px 12px;border-radius:5px;text-decoration:none;font-size:11px;font-weight:bold;display:inline-block;margin:2px;background:#1a237e;color:white}.btn-danger{background:#dc3545}.count{background:#f8d7da;color:#721c24;padding:10px 20px;border-radius:8px;display:inline-block;margin-bottom:15px;font-weight:bold}</style></head><body><div class="header"><h1>🗑️ Delete Requests</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="card"><h2>Pending</h2><div class="count">⚠️ ${requests.length}</div><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Last Login</th><th>Requested By</th><th>Action</th></tr></thead><tbody>${tr||'<tr><td colspan="6" style="text-align:center;padding:30px;">✅ No requests</td></tr>'}</tbody></table></div></div></body></html>`); });
app.get('/admin/delete-requests/approve/:id', adminAuth, async (req, res) => { if (req.session.userRole !== 'admin') return res.redirect('/admin/dashboard'); if (dbConnected) { await db.query(`DELETE FROM enrollments WHERE user_id=$1`, { bind: [req.params.id] }); await db.query(`DELETE FROM users WHERE id=$1 AND role='student'`, { bind: [req.params.id] }); } res.redirect('/admin/delete-requests'); });
app.get('/admin/delete-requests/reject/:id', adminAuth, async (req, res) => { if (req.session.userRole !== 'admin') return res.redirect('/admin/dashboard'); if (dbConnected) { await db.query(`UPDATE users SET delete_requested=false, delete_requested_by=NULL WHERE id=$1`, { bind: [req.params.id] }); } res.redirect('/admin/delete-requests'); });
app.get('/admin/request-delete/:studentId', adminAuth, async (req, res) => { if (req.session.userRole !== 'sub_admin') return res.redirect('/admin/dashboard'); if (dbConnected) { await db.query(`UPDATE users SET delete_requested=true, delete_requested_by=$1 WHERE student_id=$2 AND role='student'`, { bind: [req.session.userId, req.params.studentId] }); } res.redirect('/admin/students?msg=delete_requested'); });

