app.get('/admin/courses', adminAuth, async (req, res) => { if (req.session.userRole === 'sub_admin') { const p = await getPerms(req.session.userId); if (!p.can_manage_lessons) return res.send(`<h2>⛔ Access Denied</h2><a href="/admin/dashboard">← Back</a>`); } let courses=[]; if(dbConnected){try{const [rows]=await db.query(`SELECT * FROM courses ORDER BY created_at DESC`);courses=rows;}catch(e){}} let cc=''; if(courses.length>0){courses.forEach(c=>{cc+=`<div class="course-card"><h3>📚 ${c.title}</h3><p>${c.description||''}</p><div><a href="/admin/courses/${c.id}/lessons" class="btn-small">📖 Lessons</a><a href="/admin/courses/delete/${c.id}" class="btn-small btn-danger" onclick="return confirm('Delete?')">🗑️</a></div></div>`;});}else{cc='<p style="text-align:center;padding:30px;">No courses.</p>';} res.send(`<!DOCTYPE html><html><head><title>Courses</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:1000px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08);margin-bottom:20px}h2{color:#1a237e}input,textarea,select{width:100%;padding:12px;margin:8px 0;border:2px solid #e0e0e0;border-radius:8px;font-size:14px}button{padding:12px 25px;background:#28a745;color:white;border:none;border-radius:8px;font-weight:bold;cursor:pointer}.course-card{background:white;padding:20px;border-radius:10px;box-shadow:0 2px 8px rgba(0,0,0,0.06);margin-bottom:15px}.btn-small{padding:8px 16px;border-radius:5px;text-decoration:none;font-size:13px;font-weight:bold;display:inline-block;margin:3px;background:#1a237e;color:white}.btn-danger{background:#dc3545}</style></head><body><div class="header"><h1>📚 Courses</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="card"><h2>➕ Create</h2><form action="/admin/courses/create" method="POST"><input type="text" name="title" placeholder="Title" required><textarea name="description" placeholder="Description" rows="3"></textarea><input type="number" name="price" placeholder="Price" value="0"><select name="status"><option value="published">Published</option><option value="draft">Draft</option></select><button type="submit">➕ Create</button></form></div><h2>📖 All</h2>${cc}</div></body></html>`); });
app.post('/admin/courses/create', adminAuth, async (req, res) => { const { title, description, price, status } = req.body; if(!title) return res.send(`<script>alert('Title required!');</script>`); if(dbConnected){await db.query(`INSERT INTO courses (title,description,price,status) VALUES ($1,$2,$3,$4)`,{bind:[title,description,price,status]});} res.redirect('/admin/courses'); });
app.get('/admin/courses/delete/:id', adminAuth, async (req, res) => { if(dbConnected){await db.query(`DELETE FROM courses WHERE id=$1`,{bind:[req.params.id]});} res.redirect('/admin/courses'); });
app.get('/admin/courses/:courseId/lessons', adminAuth, async (req, res) => { const courseId=req.params.courseId; let course={title:'Unknown'},lessons=[]; if(dbConnected){try{const [c]=await db.query(`SELECT * FROM courses WHERE id=$1`,{bind:[courseId]});if(c.length>0)course=c[0];const [l]=await db.query(`SELECT * FROM lessons WHERE course_id=$1 ORDER BY order_number`,{bind:[courseId]});lessons=l;}catch(e){}} let ll=''; if(lessons.length>0){lessons.forEach(l=>{ll+=`<div class="lesson-card"><div><strong>📖 ${l.title}</strong>${l.zoom_link?'<br><small>📡 Zoom</small>':''}${l.video_url?'<br><small>🎬 Video</small>':''}</div><a href="/admin/lessons/delete/${l.id}?courseId=${courseId}" class="btn-small btn-danger" onclick="return confirm('Delete?')">🗑️</a></div>`;});}else{ll='<p style="text-align:center;padding:20px;">No lessons.</p>';} res.send(`<!DOCTYPE html><html><head><title>Lessons</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:900px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08);margin-bottom:20px}h2{color:#1a237e}input{width:100%;padding:12px;margin:8px 0;border:2px solid #e0e0e0;border-radius:8px;font-size:14px}button{padding:12px 25px;background:#28a745;color:white;border:none;border-radius:8px;font-weight:bold;cursor:pointer}.lesson-card{background:white;padding:15px 20px;border-radius:8px;box-shadow:0 2px 5px rgba(0,0,0,0.05);margin-bottom:10px;display:flex;justify-content:space-between;align-items:center}.btn-small{padding:8px 16px;border-radius:5px;text-decoration:none;font-size:13px;font-weight:bold;display:inline-block;margin:3px;background:#1a237e;color:white}.btn-danger{background:#dc3545}</style></head><body><div class="header"><h1>📖 Lessons: ${course.title}</h1><a href="/admin/courses" class="back">← Courses</a></div><div class="container"><div class="card"><h2>➕ Add</h2><form action="/admin/lessons/create" method="POST"><input type="hidden" name="courseId" value="${courseId}"><input type="text" name="title" placeholder="Title" required><input type="text" name="topicName" placeholder="Topic"><input type="text" name="zoomLink" placeholder="Zoom Link"><input type="text" name="videoUrl" placeholder="Video URL"><input type="number" name="orderNumber" placeholder="Order" value="${lessons.length+1}"><button type="submit">➕ Add</button></form></div><h2>📚 Lessons</h2>${ll}</div></body></html>`); });
app.post('/admin/lessons/create', adminAuth, async (req, res) => { try { const { courseId, title, topicName, zoomLink, videoUrl, orderNumber } = req.body; if(!title) return res.send(`<script>alert('Title required!');</script>`); if(dbConnected){await db.query(`INSERT INTO lessons (course_id,title,topic_name,zoom_link,video_url,order_number) VALUES ($1,$2,$3,$4,$5,$6)`,{bind:[courseId,title,topicName,zoomLink,videoUrl,orderNumber||0]});} res.redirect(`/admin/courses/${courseId}/lessons`); } catch(e) { res.send(`<script>alert('Error');</script>`); } });
app.get('/admin/lessons/delete/:id', adminAuth, async (req, res) => { const courseId=req.query.courseId; if(dbConnected){await db.query(`DELETE FROM lessons WHERE id=$1`,{bind:[req.params.id]});} res.redirect(`/admin/courses/${courseId}/lessons`); });

// ADMIN ENROLLMENTS
app.get('/admin/enrollments', adminAuth, async (req, res) => { let enrollments=[],courses=[],students=[]; if(dbConnected){try{const [rows]=await db.query(`SELECT e.*,u.student_id,u.full_name,u.mobile_number,c.title as course_title FROM enrollments e JOIN users u ON e.user_id=u.id JOIN courses c ON e.course_id=c.id ORDER BY e.created_at DESC`);enrollments=rows;const [cRows]=await db.query(`SELECT * FROM courses WHERE status='published'`);courses=cRows;const [sRows]=await db.query(`SELECT id,student_id,full_name FROM users WHERE role='student'`);students=sRows;}catch(e){}} let tr=''; if(enrollments.length>0){enrollments.forEach(e=>{const sc=e.status==='active'?'#28a745':e.status==='revoked'?'#dc3545':'#ffc107';const pc=e.payment_status==='verified'?'#28a745':'#17a2b8';tr+=`<tr><td><strong>${e.student_id}</strong></td><td>${e.full_name}</td><td>${e.mobile_number}</td><td>${e.course_title}</td><td><span style="background:${sc};color:white;padding:4px 10px;border-radius:12px;font-size:12px">${e.status}</span></td><td><span style="background:${pc};color:white;padding:4px 10px;border-radius:12px;font-size:12px">${e.payment_status}</span></td><td>${e.payment_proof?'<a href="'+e.payment_proof+'" target="_blank">📎</a>':'N/A'}</td><td>${e.payment_status==='pending_verification'?`<a href="/admin/enrollments/verify/${e.id}" class="btn-mini btn-approve">✅</a>`:''}${e.status==='active'?`<a href="/admin/enrollments/revoke/${e.id}" class="btn-mini btn-revoke">❌</a>`:''}<a href="/admin/enrollments/delete/${e.id}" class="btn-mini btn-delete">🗑️</a></td></tr>`;});}else{tr='<tr><td colspan="8" style="text-align:center;padding:30px;">No enrollments.</td></tr>';} let co=courses.map(c=>`<option value="${c.id}">${c.title}</option>`).join(''); let so=students.map(s=>`<option value="${s.id}">${s.student_id} - ${s.full_name}</option>`).join(''); res.send(`<!DOCTYPE html><html><head><title>Enrollments</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:1200px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08);margin-bottom:20px}h2{color:#1a237e}input,select{width:100%;padding:12px;margin:8px 0;border:2px solid #e0e0e0;border-radius:8px;font-size:14px}button{padding:12px 25px;background:#28a745;color:white;border:none;border-radius:8px;font-weight:bold;cursor:pointer}table{width:100%;border-collapse:collapse;font-size:13px}th{background:#1a237e;color:white;padding:10px;font-size:12px}td{padding:10px;border-bottom:1px solid #eee}.btn-mini{padding:5px 12px;border-radius:5px;text-decoration:none;font-size:11px;font-weight:bold;display:inline-block;margin:2px;color:white}.btn-approve{background:#28a745}.btn-revoke{background:#dc3545}.btn-delete{background:#6c757d}.info-box{background:#e8f5e9;color:#2e7d32;padding:15px;border-radius:8px;margin-bottom:20px}</style></head><body><div class="header"><h1>💰 Payments</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="info-box">💡 Student pays → Admin Approves → Access</div><div class="card"><h2>➕ Manual Enroll</h2><form action="/admin/enrollments/create" method="POST"><select name="studentId" required><option value="">Student</option>${so}</select><select name="courseId" required><option value="">Course</option>${co}</select><select name="status"><option value="active">Active</option><option value="pending">Pending</option></select><button type="submit">➕ Enroll</button></form></div><div class="card"><h2>All</h2><table><thead><tr><th>ID</th><th>Name</th><th>Mobile</th><th>Course</th><th>Status</th><th>Payment</th><th>Proof</th><th>Action</th></tr></thead><tbody>${tr}</tbody></table></div></div></body></html>`); });
app.post('/admin/enrollments/create', adminAuth, async (req, res) => { const { studentId, courseId, status } = req.body; if(dbConnected){await db.query(`INSERT INTO enrollments (user_id,course_id,status,payment_status) VALUES ($1,$2,$3,$4)`,{bind:[studentId,courseId,status||'active',status==='active'?'verified':'unpaid']});} res.redirect('/admin/enrollments'); });
app.get('/admin/enrollments/verify/:id', adminAuth, async (req, res) => { if(dbConnected){await db.query(`UPDATE enrollments SET payment_status='verified',status='active',enrolled_at=NOW() WHERE id=$1`,{bind:[req.params.id]});} res.redirect('/admin/enrollments'); });
app.get('/admin/enrollments/revoke/:id', adminAuth, async (req, res) => { if(dbConnected){await db.query(`UPDATE enrollments SET status='revoked',revoked_at=NOW() WHERE id=$1`,{bind:[req.params.id]});} res.redirect('/admin/enrollments'); });
app.get('/admin/enrollments/activate/:id', adminAuth, async (req, res) => { if(dbConnected){await db.query(`UPDATE enrollments SET status='active' WHERE id=$1`,{bind:[req.params.id]});} res.redirect('/admin/enrollments'); });
app.get('/admin/enrollments/delete/:id', adminAuth, async (req, res) => { if(dbConnected){await db.query(`DELETE FROM enrollments WHERE id=$1`,{bind:[req.params.id]});} res.redirect('/admin/enrollments'); });

// ADMIN STUDENTS
app.get('/admin/students', adminAuth, async (req, res) => { let students=[]; if(dbConnected){try{const [rows]=await db.query(`SELECT id,student_id,full_name,mobile_number,school_name,district,nic_number,is_active,last_login_at,delete_requested FROM users WHERE role='student' ORDER BY created_at DESC`);students=rows;}catch(e){}} const isMainAdmin = req.session.userRole === 'admin'; let tr=''; if(students.length>0){students.forEach(s=>{const delBtn = isMainAdmin ? `<a href="/admin/students/delete/${s.id}" class="btn-mini btn-danger" onclick="return confirm('Delete?')">🗑️</a>` : (s.delete_requested ? '<span class="badge inactive">Requested</span>' : `<a href="/admin/request-delete/${s.student_id}" class="btn-mini" style="background:#dc3545;" onclick="return confirm('Request delete?')">📩 Request</a>`); tr+=`<tr><td><strong>${s.student_id}</strong></td><td>${s.full_name}</td><td>${s.mobile_number}</td><td>${s.school_name||'N/A'}</td><td>${s.district||'N/A'}</td><td>${s.nic_number||'N/A'}</td><td><span class="badge ${s.is_active?'active':'inactive'}">${s.is_active?'Active':'Inactive'}</span></td><td>${s.last_login_at?new Date(s.last_login_at).toLocaleDateString():'Never'}</td><td>${delBtn}</td></tr>`;});}else{tr='<tr><td colspan="9" style="text-align:center;padding:30px;">No students.</td></tr>';} res.send(`<!DOCTYPE html><html><head><title>Students</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:1200px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08)}h2{color:#1a237e}table{width:100%;border-collapse:collapse}th{background:#1a237e;color:white;padding:12px;font-size:13px}td{padding:12px;border-bottom:1px solid #eee;font-size:13px}.badge{padding:5px 12px;border-radius:20px;font-size:12px;font-weight:bold}.active{background:#d4edda;color:#155724}.inactive{background:#f8d7da;color:#721c24}.btn-mini{padding:5px 12px;border-radius:5px;text-decoration:none;font-size:11px;font-weight:bold;display:inline-block;margin:2px;background:#1a237e;color:white}.btn-danger{background:#dc3545}.count{background:#e3f2fd;color:#1565c0;padding:10px 20px;border-radius:8px;display:inline-block;margin-bottom:15px;font-weight:bold}</style></head><body><div class="header"><h1>👥 Students</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="card"><h2>All</h2><div class="count">📊 ${students.length}</div><div style="margin-bottom:20px"><input type="text" id="si" placeholder="🔍 Search" onkeyup="searchTable()" style="padding:12px;border:2px solid #e0e0e0;border-radius:8px;width:300px"></div><table id="st"><thead><tr><th>ID</th><th>Name</th><th>Mobile</th><th>School</th><th>District</th><th>NIC</th><th>Status</th><th>Login</th><th>Action</th></tr></thead><tbody>${tr}</tbody></table></div></div><script>function searchTable(){var i=document.getElementById('si'),f=i.value.toUpperCase(),t=document.getElementById('st'),r=t.getElementsByTagName('tr');for(var j=1;j<r.length;j++){var d=r[j].getElementsByTagName('td'),o=false;for(var k=0;k<d.length;k++){if(d[k]&&d[k].textContent.toUpperCase().indexOf(f)>-1){o=true;break}}r[j].style.display=o?'':'none'}}</script></body></html>`); });
app.get('/admin/students/delete/:id', adminAuth, async (req, res) => { if(req.session.userRole!=='admin') return res.redirect('/admin/students'); if(dbConnected){await db.query(`DELETE FROM enrollments WHERE user_id=$1`,{bind:[req.params.id]}); await db.query(`DELETE FROM users WHERE id=$1 AND role='student'`,{bind:[req.params.id]});} res.redirect('/admin/students'); });

// ADMIN INACTIVE & ANALYTICS
app.get('/admin/inactivity', adminAuth, async (req, res) => { let inactive=[]; if(dbConnected){try{const [rows]=await db.query(`SELECT student_id,full_name,mobile_number,last_login_at FROM users WHERE role='student' AND (last_login_at IS NULL OR last_login_at < NOW() - INTERVAL '7 days') ORDER BY last_login_at ASC NULLS FIRST`);inactive=rows;}catch(e){}} let tr=''; if(inactive.length>0){inactive.forEach(s=>{const days=s.last_login_at?Math.floor((Date.now()-new Date(s.last_login_at))/(86400000)):'Never';tr+=`<tr><td><strong>${s.student_id}</strong></td><td>${s.full_name}</td><td>${s.mobile_number}</td><td>${s.last_login_at?new Date(s.last_login_at).toLocaleDateString():'Never'}</td><td><span class="badge">${days} days</span></td></tr>`;});}else{tr='<tr><td colspan="5" style="text-align:center;color:#28a745;">✅ All active!</td></tr>';} res.send(`<!DOCTYPE html><html><head><title>Inactive</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#dc3545,#c82333);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:1000px;margin:25px auto;padding:0 20px}.card{background:white;padding:25px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08)}h2{color:#dc3545}table{width:100%;border-collapse:collapse}th{background:#dc3545;color:white;padding:12px;font-size:13px}td{padding:12px;border-bottom:1px solid #eee}.badge{background:#f8d7da;color:#721c24;padding:5px 12px;border-radius:20px;font-size:12px;font-weight:bold}.count{background:#f8d7da;color:#721c24;padding:10px 20px;border-radius:8px;display:inline-block;margin-bottom:15px;font-weight:bold}</style></head><body><div class="header"><h1>🚨 Inactive</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="card"><h2>7+ Days</h2><div class="count">⚠️ ${inactive.length}</div><table><thead><tr><th>ID</th><th>Name</th><th>Mobile</th><th>Last Login</th><th>Status</th></tr></thead><tbody>${tr}</tbody></table></div></div></body></html>`); });
app.get('/admin/analytics', adminAuth, async (req, res) => { let t=0,a=0,i=0; if(dbConnected){try{const [r1]=await db.query(`SELECT COUNT(*) as c FROM users WHERE role='student'`);t=r1[0]?.c||0;const [r2]=await db.query(`SELECT COUNT(*) as c FROM users WHERE role='student' AND last_login_at > NOW() - INTERVAL '1 day'`);a=r2[0]?.c||0;const [r3]=await db.query(`SELECT COUNT(*) as c FROM users WHERE role='student' AND (last_login_at IS NULL OR last_login_at < NOW() - INTERVAL '7 days')`);i=r3[0]?.c||0;}catch(e){}} res.send(`<!DOCTYPE html><html><head><title>Analytics</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.back{color:white;text-decoration:none}.container{max-width:900px;margin:25px auto;padding:0 20px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:20px}.card{background:white;padding:30px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08);text-align:center}.card .icon{font-size:40px;margin-bottom:10px}.card .num{font-size:42px;font-weight:bold;color:#1a237e}.card .label{color:#666;font-size:14px}.green{border-top:4px solid #28a745}.blue{border-top:4px solid #1a237e}.red{border-top:4px solid #dc3545}</style></head><body><div class="header"><h1>📊 Analytics</h1><a href="/admin/dashboard" class="back">← Dashboard</a></div><div class="container"><div class="cards"><div class="card blue"><div class="icon">👥</div><div class="num">${t}</div><div class="label">Total</div></div><div class="card green"><div class="icon">✅</div><div class="num">${a}</div><div class="label">Today</div></div><div class="card red"><div class="icon">🚨</div><div class="num">${i}</div><div class="label">Inactive</div></div></div></div></body></html>`); });

